/**
 * POST /api/build/artifact — generate ONE builder-pivot artifact from the user's
 * idea (#207). This is the wiring that makes the /build flow real: each artifact
 * (thesis, wedge, PRD, data model, …) is generated by Claude from the founder's
 * idea, instead of rendering the hardcoded design mock.
 *
 * Provider order (reuses the SAME completion stack as codegen, no new provider):
 *   1. Amazon Bedrock (Config C) or direct Anthropic  — lib/build/claude-completion
 *   2. AINative chat-completions (claude-sonnet-4.5)   — OpenAI-compatible, server key
 * Both work server-side for ANY visitor (incl. anonymous), so nobody is blocked.
 * The enterprise-gated agent-swarm path is reserved for the paid real-build step
 * (see core#6422).
 *
 * Body: { view, idea, track, companyName?, prior?, feedback? }
 *   feedback (GR-16 #329): founder's review notes when REGENERATING an artifact —
 *   appended to the generation prompt so the redraft applies the requested changes.
 * Returns: { view, content (parsed JSON per artifact schema), provider, model }
 */

import { NextRequest } from 'next/server'
import OpenAI from 'openai'
import * as Sentry from '@sentry/nextjs'
import { ARTIFACT_PROMPTS, type ArtifactContext } from '@/lib/build/artifact-prompts'
import { feedbackInstruction } from '@/lib/build/artifact-edit'
import { getClaudeCompletion } from '@/lib/build/claude-completion'
import { auth } from '@/app/(auth)/auth'
import { getPlanStatus } from '@/lib/ainative/plan'
import { modelsForTier } from '@/lib/build/tier-models'
import { loadCoreProfile } from '@/lib/build/profile'
import { languageInstruction, normalizeLanguage, DEFAULT_CONTENT_LANGUAGE } from '@/lib/build/content-language'

export const runtime = 'nodejs'

// A hung provider call (no network-level error, just never resolving) used to
// stall a generation forever with no client-visible signal. Bound every
// provider call so a hang surfaces as a normal timeout failure instead.
const PROVIDER_TIMEOUT_MS = 20_000

/**
 * The OpenAI SDK only surfaces `error.error` (the OpenAI-shaped `{error:
 * {message}}` envelope) on a thrown APIError — it reads the raw response body
 * once internally to build that shape, then DISCARDS it. Core's actual error
 * contract is `{detail, error_code, next_action}` (no top-level `error` key at
 * all, see app/main.py's http_exception_handler in the core repo), so
 * `error.error` is always undefined and the SDK falls back to a useless
 * "{status} status code (no body)" message — even though core sent a real,
 * informative body every time. (Ref #360.)
 *
 * makeCapturingFetch returns a FRESH fetch + box per call — this route handler
 * runs on a shared warm Node.js instance across concurrent requests, so a
 * single module-level "last error" variable would let one request's error body
 * leak into another's log under load (exactly the concurrency this bug was
 * found under). The box is a plain object, not a module let, so each call to
 * ainative.chat.completions.create() below gets its own private capture.
 */
function makeCapturingFetch(): { fetch: typeof fetch; box: { body: string | null } } {
  const box = { body: null as string | null }
  const capturingFetch: typeof fetch = async (input, init) => {
    const res = await fetch(input, init)
    if (!res.ok) {
      try {
        box.body = await res.clone().text()
      } catch {
        box.body = null
      }
    }
    return res
  }
  return { fetch: capturingFetch, box }
}

const AINATIVE_BASE_URL = (process.env.AINATIVE_API_URL || 'https://api.ainative.studio') + '/v1'
const AINATIVE_API_KEY = process.env.AINATIVE_API_KEY || process.env.API_Key || process.env.ZERODB_API_KEY || ''
const AINATIVE_FALLBACK = 'nous-coder'

/**
 * Resolve the caller's plan tier from their session, so generation uses the
 * tier-appropriate Claude model (Haiku 4.5 / Sonnet 4.5 / Opus 4.5). Anonymous
 * or errored callers get the entry tier (hobbyist → Haiku) — fast + free.
 */
async function resolveTier(): Promise<string> {
  try {
    const session = await auth()
    const accessToken = (session as any)?.accessToken
    if (!accessToken) return 'hobbyist'
    const status = await getPlanStatus(accessToken)
    return status.tier || 'hobbyist'
  } catch {
    return 'hobbyist'
  }
}

/**
 * Resolve the founder's content language (#57). Prefers an explicit body override
 * (the client already knows the setting → no round-trip) and otherwise reads it
 * from the signed-in user's real account. Anonymous/errored callers → English.
 */
async function resolveContentLanguage(bodyLanguage: unknown): Promise<string> {
  if (typeof bodyLanguage === 'string' && bodyLanguage.trim()) {
    return normalizeLanguage(bodyLanguage)
  }
  try {
    const session = await auth()
    const accessToken = (session as any)?.accessToken
    const type = (session as any)?.user?.type
    if (!accessToken || type === 'guest') return DEFAULT_CONTENT_LANGUAGE
    const profile = await loadCoreProfile(accessToken)
    return profile.contentLanguage || DEFAULT_CONTENT_LANGUAGE
  } catch {
    return DEFAULT_CONTENT_LANGUAGE
  }
}

/** Pull the first balanced JSON object out of a model response (handles ```json fences, stray prose). */
function parseJson(raw: string): unknown | null {
  if (!raw) return null
  let s = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()
  const start = s.indexOf('{')
  const end = s.lastIndexOf('}')
  if (start === -1 || end === -1 || end < start) return null
  s = s.slice(start, end + 1)
  try {
    return JSON.parse(s)
  } catch {
    return null
  }
}

export async function POST(request: NextRequest) {
  let body: any
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'invalid JSON body' }, { status: 400 })
  }

  const { view, idea, track, companyName, prior, feedback } = body || {}
  if (!view || !ARTIFACT_PROMPTS[view]) {
    return Response.json({ error: `unknown or missing view: ${view}` }, { status: 400 })
  }
  if (!idea || typeof idea !== 'string' || idea.trim().length < 3) {
    return Response.json({ error: 'idea is required' }, { status: 400 })
  }

  const spec = ARTIFACT_PROMPTS[view]
  // Founder's content language (#57) — drives the OUTPUT language of the artifact.
  const contentLanguage = await resolveContentLanguage(body?.contentLanguage)
  const ctx: ArtifactContext = {
    idea: idea.trim().slice(0, 4000),
    track: track === 'company' ? 'company' : 'app',
    companyName: typeof companyName === 'string' ? companyName.slice(0, 120) : undefined,
    prior: prior && typeof prior === 'object' ? prior : {},
    contentLanguage,
  }
  // Append the language instruction (empty for English) so generated string VALUES
  // are written in the founder's language while the JSON schema stays parseable.
  const langInstr = languageInstruction(contentLanguage)
  const system =
    spec.system + `\nRequired JSON schema: ${spec.schemaHint}` + (langInstr ? `\n${langInstr}` : '')
  // Regeneration feedback (GR-16 #329): appended to THIS view's prompt so the
  // redraft applies the founder's requested changes. '' when absent/blank.
  const user = spec.user(ctx) + feedbackInstruction(typeof feedback === 'string' ? feedback : '')

  // Tier → model: Hobbyist=Haiku 4.5, Pro/Scale=Sonnet 4.5, Enterprise=Opus 4.5.
  // An explicit BUILD_ARTIFACT_MODEL env still overrides (ops escape hatch).
  const tierModels = modelsForTier(await resolveTier())
  const bedrockModel = process.env.BUILD_ARTIFACT_MODEL || tierModels.bedrockModel

  // Every attempt this request makes across both providers — logged to Sentry
  // as breadcrumbs so a final failure carries the FULL story (which providers/
  // models were tried and how each one specifically failed), not just the last
  // error. Nothing is sent to Sentry unless every attempt below is exhausted.
  const attemptLog: string[] = []
  // One extra "fix your JSON" pass per provider response — this is the actual
  // most common real-world failure (the model wrote prose around the JSON, or
  // truncated it), and it used to burn the provider's ONE shot and fall through
  // immediately instead of just asking the same model to repair its own output.
  const repairInstruction =
    '\n\nYour previous reply could not be parsed as JSON. Reply with ONLY the raw JSON object — no prose, no markdown fences, no trailing commentary.'

  // 1) Primary: Bedrock / direct Anthropic (provider-agnostic .messages.create).
  // Bedrock accepts a per-call model override, so we invoke the TIER's model, not
  // the client default. (Direct Anthropic ignores the Bedrock profile id and uses
  // its own configured Claude model — still a Claude, just not tier-specific.)
  const claude = getClaudeCompletion()
  if (claude) {
    const model = claude.provider === 'bedrock' ? bedrockModel : claude.model
    for (let pass = 0; pass < 2; pass++) {
      try {
        const res = await claude.client.messages.create(
          {
            model,
            max_tokens: 1600,
            temperature: 0.55,
            system,
            messages: [{ role: 'user', content: pass === 0 ? user : user + repairInstruction }],
          },
          { signal: AbortSignal.timeout(PROVIDER_TIMEOUT_MS) },
        )
        const text = (res.content || [])
          .filter((b: any) => b.type === 'text')
          .map((b: any) => b.text)
          .join('\n')
        const content = parseJson(text)
        if (content) {
          return Response.json({ view, content, provider: claude.provider, model, tier: tierModels.tier })
        }
        attemptLog.push(`${claude.provider}/${model} pass ${pass + 1}: unparseable JSON`)
      } catch (e: any) {
        const msg = e?.message?.slice(0, 120) || String(e)
        attemptLog.push(`${claude.provider}/${model} pass ${pass + 1}: ${msg}`)
        // A repair pass only makes sense after a parseable-but-wrong response;
        // a hard call failure (timeout, 5xx, network) won't be fixed by asking
        // the same broken call to try again — move on to the next provider now.
        break
      }
    }
  }

  // 2) Fallback: AINative chat-completions (tier's Claude model, then a free model)
  for (const model of [tierModels.ainativeModel, AINATIVE_FALLBACK]) {
    for (let pass = 0; pass < 2; pass++) {
      const { fetch: capturingFetch, box } = makeCapturingFetch()
      // maxRetries: 0 — the SDK retries 429/5xx up to twice by DEFAULT, which
      // stacks silently underneath our own pass/model retry loop (up to 3x
      // real HTTP calls per logical attempt here, unlogged). Under the exact
      // concurrent-load conditions that cause 429s in the first place, that
      // amplification makes things worse, not better (Ref #360).
      const ainative = new OpenAI({ apiKey: AINATIVE_API_KEY, baseURL: AINATIVE_BASE_URL, fetch: capturingFetch, maxRetries: 0 })
      try {
        const res = await ainative.chat.completions.create(
          {
            model,
            max_tokens: 1600,
            temperature: 0.55,
            messages: [
              { role: 'system', content: system },
              { role: 'user', content: pass === 0 ? user : user + repairInstruction },
            ],
          },
          { signal: AbortSignal.timeout(PROVIDER_TIMEOUT_MS) },
        )
        const text = res.choices?.[0]?.message?.content || ''
        const content = parseJson(text)
        if (content) {
          return Response.json({ view, content, provider: 'ainative', model, tier: tierModels.tier })
        }
        attemptLog.push(`ainative/${model} pass ${pass + 1}: unparseable JSON`)
      } catch (e: any) {
        // e.message is the SDK's OWN formatting, which is "{status} status code
        // (no body)" whenever core's response doesn't match the OpenAI error
        // shape — true for every core error, since core uses {detail, error_code}.
        // box.body is core's REAL raw body, captured by capturingFetch before
        // the SDK discarded it (Ref #360).
        const status = e?.status
        const raw = box.body?.slice(0, 200)
        const msg = raw ? `${status ?? ''} ${raw}`.trim() : (e?.message?.slice(0, 120) || String(e))
        attemptLog.push(`ainative/${model} pass ${pass + 1}: ${msg}`)
        break
      }
    }
  }

  console.warn(`[build/artifact] ${view}: all providers exhausted — ${attemptLog.join(' | ')}`)
  Sentry.captureMessage(`build/artifact generation exhausted: ${view}`, {
    level: 'error',
    tags: { view, track: ctx.track, tier: tierModels.tier },
    extra: { attempts: attemptLog, ideaPreview: ctx.idea.slice(0, 200) },
  })

  return Response.json(
    { error: 'generation_unavailable', view },
    { status: 503 },
  )
}
